export function createLibraryReveal(React){const{createElement:h,useRef:R,useEffect:E}=React;return function Reveal({children}){const root=R(null);E(()=>{const el=root.current;if(!el)return;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');let overlay=null,timer=null,current=null;function stop(){clearTimeout(timer);overlay?.remove();overlay=null;current=null}function enter(e){const img=e.target.closest?.('img');if(!img||img===current||!el.contains(img)||reduced.matches)return;stop();const r=img.getBoundingClientRect();if(r.width<70||r.height<70)return;current=img;overlay=document.createElement('div');overlay.className='library-hover-loading';overlay.setAttribute('aria-hidden','true');Object.assign(overlay.style,{position:'fixed',left:r.left+'px',top:r.top+'px',width:r.width+'px',height:r.height+'px',borderRadius:getComputedStyle(img).borderRadius});overlay.appendChild(document.createElement('i'));document.body.appendChild(overlay);timer=setTimeout(()=>{overlay?.remove();overlay=null},600)}function leave(e){if(e.target===current)stop()}el.addEventListener('pointerover',enter);el.addEventListener('pointerout',leave);window.addEventListener('scroll',stop,true);document.addEventListener('visibilitychange',stop);return()=>{stop();el.removeEventListener('pointerover',enter);el.removeEventListener('pointerout',leave);window.removeEventListener('scroll',stop,true);document.removeEventListener('visibilitychange',stop)}},[]);return h('div',{ref:root,className:'library-reveal-surface'},children)};}
